import json,itertools
from scipy.stats import pearsonr,spearmanr
def parse(s): return {t[:2]:int(t[2:]) for t in s.split()}
M=json.load(open('statemaps.json'))
pop2={
'pickleball':parse("WY100 UT65 HI61 FL58 CO56 AZ56 MN54 WA51 CA51 NV51 NC46 GA45 TX45 NJ45 CT42 SC42 TN42 OR42 ID42 MI42 KS41 VA41 MA40 MO40 NH39 WI39 DE38 NY38 IL37 VT37 MD37 AR36 AL36 OH36 NE35 NM35 RI35 LA34 IN34 PA33 KY32 MT32 IA32 OK31 DC31 ME30 ND30 AK29 MS28 SD28 WV20"),
'pumpkin spice latte':parse("WY100 KS96 NM96 OH93 IN92 AZ89 CO87 NE86 OR84 TN84 VT84 WV83 WI83 ND83 DE81 SC81 VA81 IL81 NV81 ID81 KY80 MI80 PA78 NC76 OK76 CA75 WA73 IA73 SD72 MT72 MO72 NJ70 MD70 CT69 MN69 ME69 NH67 FL67 UT66 TX66 GA64 MA64 HI63 AR61 NY61 AK61 RI58 AL55 DC53 LA47 MS44"),
'golf':parse("WY100 SC81 MN74 ND73 UT73 SD72 NE72 WI71 IA67 CO67 HI67 ID66 MI65 AZ65 FL65 MT64 MA64 NH63 NC62 TN62 OH61 KS61 MO58 CT58 ME57 PA57 IN57 IL57 OR56 RI54 AL54 KY53 NV52 OK51 NJ51 GA50 DE50 VT49 NM48 VA48 WA47 NY46 MS46 AR46 TX45 WV45 CA45 MD44 LA43 DC40 AK28"),
'true crime':parse("WY100 ND62 WV62 VT58 KS58 NH58 NC57 UT57 IA56 TN56 CO55 IN55 OK55 MT55 DC54 KY54 RI54 AR54 MO53 MI53 NE53 OH53 ME53 WA53 SC52 MS52 MA52 GA51 PA51 NM51 ID50 OR50 TX50 DE50 AL49 VA49 SD49 MD49 LA48 IL48 WI48 AZ47 MN47 CA47 NV46 AK45 FL44 CT43 NY43 NJ41 HI28"),
'country music':parse("TN100 WY85 KY58 WV57 SC53 OK51 AR51 SD48 AL48 KS46 MT46 IN45 ND45 OH45 MO44 IA44 MS43 NC42 NE41 VT41 PA41 WI38 LA38 DE37 VA37 MN36 ME36 ID35 NM35 GA34 FL34 MI34 TX34 AZ33 NH31 OR31 NJ31 NV30 CO29 IL29 WA28 MD28 AK27 UT27 CA27 NY26 RI25 MA24 CT23 DC21 HI20")}
M['pop'].update(pop2); json.dump(M,open('statemaps.json','w'))
res=[]
for p,b in itertools.product(pop2,M['beauty']):
    st=[s for s in pop2[p] if s in M['beauty'][b] and s not in ('WY','DC','RI','TN')]
    x=[pop2[p][s] for s in st];y=[M['beauty'][b][s] for s in st]
    r,pv=pearsonr(x,y);rs=spearmanr(x,y)[0];res.append((abs(rs),p,b,round(r,2),round(rs,2),round(pv,4),len(st)))
for t in sorted(res,reverse=True)[:12]: print(t[1:])
